local UIActivityTimeLimitedTaskCellNode = Class('UIActivityTimeLimitedTaskCellNode')

function UIActivityTimeLimitedTaskCellNode:__init()
end

function UIActivityTimeLimitedTaskCellNode:__delete()
end

function UIActivityTimeLimitedTaskCellNode:Awake()
    SetButtonAction(self.FontStyleButton, function ()
        if type(self:GetBtnCB()) == "function" then
            self:GetBtnCB()(self:GetTaskId(), self)
        else
            GameUtils.Toast("please set button callback")
        end
    end)
end

function UIActivityTimeLimitedTaskCellNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

